//! SpanDSP FFI bindings.
//!
//! This module provides Rust bindings to the SpanDSP C library.
//! Bindings are automatically generated by bindgen during the build process.

#![allow(non_upper_case_globals)]
#![allow(non_camel_case_types)]
#![allow(non_snake_case)]
#![allow(dead_code)]
#![allow(improper_ctypes)]
#![allow(clippy::all)]

// Include the generated bindings from build.rs when spandsp-native feature is enabled
#[cfg(feature = "spandsp-native")]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/spandsp_bindings.rs"));
}

#[cfg(feature = "spandsp-native")]
pub use generated::*;

// ========================================
// Native UDPTL bindings (from vendor/spandsp/tests/udptl.c)
// These are NOT part of the SpanDSP shared library — they come from
// the separately compiled udptl.c (Steve Underwood's reference implementation).
// ========================================
#[cfg(feature = "spandsp-native")]
mod native_udptl {
    use std::os::raw::{c_int, c_void};

    /// Opaque UDPTL state (matches struct udptl_state_s from udptl.h)
    #[repr(C)]
    pub struct udptl_state_t {
        _private: [u8; 0],
    }

    /// UDPTL RX callback: called for each decoded IFP packet
    pub type udptl_rx_packet_handler_t = Option<
        unsafe extern "C" fn(
            user_data: *mut c_void,
            msg: *const u8,
            len: c_int,
            seq_no: c_int,
        ) -> c_int,
    >;

    /// UDPTL error correction modes
    pub const UDPTL_ERROR_CORRECTION_NONE: c_int = 0;
    pub const UDPTL_ERROR_CORRECTION_FEC: c_int = 1;
    pub const UDPTL_ERROR_CORRECTION_REDUNDANCY: c_int = 2;

    extern "C" {
        /// Initialize a UDPTL context.
        pub fn udptl_init(
            s: *mut udptl_state_t,
            ec_scheme: c_int,
            span: c_int,
            entries: c_int,
            rx_packet_handler: udptl_rx_packet_handler_t,
            user_data: *mut c_void,
        ) -> *mut udptl_state_t;

        /// Process a received UDPTL packet (decodes and delivers IFP via callback).
        pub fn udptl_rx_packet(
            s: *mut udptl_state_t,
            buf: *const u8,
            len: c_int,
        ) -> c_int;

        /// Build a UDPTL packet from an IFP payload.
        /// Returns the total packet length, or -1 on error.
        pub fn udptl_build_packet(
            s: *mut udptl_state_t,
            buf: *mut u8,
            msg: *const u8,
            msg_len: c_int,
        ) -> c_int;

        /// Set error correction parameters.
        pub fn udptl_set_error_correction(
            s: *mut udptl_state_t,
            ec_scheme: c_int,
            span: c_int,
            entries: c_int,
        ) -> c_int;

        /// Set the maximum datagram size the far end accepts.
        pub fn udptl_set_far_max_datagram(
            s: *mut udptl_state_t,
            max_datagram: c_int,
        ) -> c_int;

        /// Set the maximum datagram size we accept.
        pub fn udptl_set_local_max_datagram(
            s: *mut udptl_state_t,
            max_datagram: c_int,
        ) -> c_int;

        /// Free a UDPTL context.
        pub fn udptl_free(s: *mut udptl_state_t) -> c_int;

        /// Release a UDPTL context (does not free memory).
        pub fn udptl_release(s: *mut udptl_state_t) -> c_int;
    }
}

#[cfg(feature = "spandsp-native")]
pub use native_udptl::*;

