/// Sample rate for fax audio (8kHz)
pub const FAX_SAMPLE_RATE: u32 = 8000;

/// Samples per 20ms frame (standard RTP packet)
pub const FAX_SAMPLES_PER_FRAME: usize = 160;

/// Check if SpanDSP native support is available
pub const fn is_spandsp_available() -> bool {
    cfg!(feature = "spandsp-native")
}

/// Modem type constants per ITU-T T.30
pub mod modems {
    /// V.27ter - 2400/4800 bps (mandatory for Group 3)
    pub const T30_SUPPORT_V27TER: i32 = 0x01;
    /// V.29 - 7200/9600 bps
    pub const T30_SUPPORT_V29: i32 = 0x02;
    /// V.17 - 7200-14400 bps
    pub const T30_SUPPORT_V17: i32 = 0x04;
    /// V.34 - 2400-33600 bps (Super G3)
    pub const T30_SUPPORT_V34: i32 = 0x08;
    
    /// Standard fax modems (V.27ter + V.29 + V.17)
    pub const T30_SUPPORT_STANDARD: i32 = T30_SUPPORT_V27TER | T30_SUPPORT_V29 | T30_SUPPORT_V17;
    
    /// All modems including Super G3
    pub const T30_SUPPORT_ALL: i32 = T30_SUPPORT_STANDARD | T30_SUPPORT_V34;
}

/// T.4 bilevel image resolution flags (from spandsp/t4_rx.h)
/// Used with t30_set_supported_bilevel_resolutions()
pub mod resolutions {
    /// Standard FAX resolution 204dpi x 98dpi
    pub const T4_RESOLUTION_R8_STANDARD: i32 = 0x01;
    /// Fine FAX resolution 204dpi x 196dpi
    pub const T4_RESOLUTION_R8_FINE: i32 = 0x02;
    /// Super-fine FAX resolution 204dpi x 391dpi
    pub const T4_RESOLUTION_R8_SUPERFINE: i32 = 0x04;
    /// Double FAX resolution 408dpi x 391dpi
    pub const T4_RESOLUTION_R16_SUPERFINE: i32 = 0x08;
    /// 200dpi x 100dpi
    pub const T4_RESOLUTION_200_100: i32 = 0x20;
    /// 200dpi x 200dpi
    pub const T4_RESOLUTION_200_200: i32 = 0x40;
    /// 200dpi x 400dpi
    pub const T4_RESOLUTION_200_400: i32 = 0x80;
    /// 300dpi x 300dpi
    pub const T4_RESOLUTION_300_300: i32 = 0x100;
    /// 400dpi x 400dpi
    pub const T4_RESOLUTION_400_400: i32 = 0x400;
    /// 600dpi x 600dpi
    pub const T4_RESOLUTION_600_600: i32 = 0x1000;
    /// 1200dpi x 1200dpi
    pub const T4_RESOLUTION_1200_1200: i32 = 0x4000;

    /// Standard support: R8 standard + fine (most common fax resolutions)
    pub const T4_RESOLUTION_FAX_STANDARD: i32 = T4_RESOLUTION_R8_STANDARD | T4_RESOLUTION_R8_FINE;
    /// Extended support: also includes 200x200 and 300x300
    pub const T4_RESOLUTION_FAX_EXTENDED: i32 = T4_RESOLUTION_FAX_STANDARD
        | T4_RESOLUTION_R8_SUPERFINE
        | T4_RESOLUTION_200_200
        | T4_RESOLUTION_300_300;
}

